<template>
  <div class="gallery-experience-study">
    <div class="experience-tabs" role="tablist" aria-label="Exhibition design" @keydown="moveTab">
      <button v-for="feature in features" :id="tabId(feature.id)" :key="feature.id" type="button" role="tab" :aria-selected="selected === feature.id" :aria-controls="panelId(feature.id)" :tabindex="selected === feature.id ? 0 : -1" @click="selected = feature.id">
        <ExhibitionFeatureIcon :feature="feature.id" />
        <span>{{ feature.label }}</span>
      </button>
    </div>
    <section v-for="feature in features" v-show="selected === feature.id" :id="panelId(feature.id)" :key="feature.id" class="experience-panel" role="tabpanel" :aria-labelledby="tabId(feature.id)" tabindex="0">
      <div class="experience-row">
        <div class="experience-copy">
          <h4>{{ feature.title }}</h4>
          <p>{{ feature.copy }}</p>
        </div>
        <GalleryStudyFilm v-if="feature.video" :src="film(feature.video)" :poster="image(feature.image)" :captions="feature.sound ? film('audio', 'vtt') : undefined" :label="feature.caption" :sound="feature.sound" :active="selected === feature.id" />
        <figure v-else>
          <ExpandableProjectMedia :title="feature.title" :aspect-ratio="1920/1046">
            <div class="experience-image">
              <img :src="image(feature.image)" :alt="feature.alt" width="1920" height="1046" loading="lazy" />
              <svg v-if="feature.id === 'rooms'" class="rooms-focus-mask" viewBox="0 0 1920 1046" aria-hidden="true">
                <defs><mask :id="maskId"><rect width="1920" height="1046" fill="white"/><rect x="32" y="132" width="489" height="728" rx="2" fill="black"/></mask></defs>
                <rect width="1920" height="1046" fill="#171610" fill-opacity=".48" :mask="`url(#${maskId})`"/>
              </svg>
            </div>
          </ExpandableProjectMedia>
          <figcaption>{{ feature.caption }}</figcaption>
        </figure>
      </div>
      <details v-if="feature.mechanism" class="experience-mechanism">
        <summary>{{ feature.mechanism.title }}<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8h10"/><path class="disclosure-vertical" d="M8 3v10"/></svg></summary>
        <div class="mechanism-copy"><p v-for="paragraph in feature.mechanism.paragraphs" :key="paragraph">{{ paragraph }}</p></div>
      </details>
    </section>
  </div>
</template>
<script>
import GalleryStudyFilm from './GalleryStudyFilm.vue';
import ExpandableProjectMedia from './ExpandableProjectMedia.vue';
import ExhibitionFeatureIcon from './ExhibitionFeatureIcon.vue';

const features = [
  {
    id: 'arrival', label: 'Arrival', title: 'Arriving in the exhibition', image: 'arrival', caption: 'Getting started',
    copy: 'The opening passage introduces the question behind the exhibition. The first room is visible ahead, and a brief guide helps visitors find their way into the story.',
    alt: 'The exhibition entrance, its opening narrative and the introductory guide',
  },
  {
    id: 'walls', label: 'Wall writing', title: 'A narrative on the walls', image: 'wall-writing', caption: 'A life across places',
    copy: 'Chapter introductions give the works in each room a shared context. Titles above the doorways lead into the next chapter, and an afterword closes the visit.',
    alt: 'A chapter introduction printed on the gallery wall beside an original photograph',
  },
  {
    id: 'objects', label: 'Objects', title: 'Material with a physical form', image: 'globe', caption: 'Where I’ve Wandered',
    copy: 'A record of places becomes a globe. Photographs hang on the walls, personal writing sits on reading stands, and visitors can try the interactive projects. Each display takes its form from the material it holds.',
    alt: 'The original travel record presented as a globe with pins marking the places Henry has visited',
    mechanism: {
      title: 'How material becomes an exhibit',
      paragraphs: ['The exhibition reads the type of each source and gives it a display form. Photographs become framed works, writing becomes a reading surface, and geographical records become globes. The display’s dimensions and viewing distance help determine its position in the room.', 'Interactive projects open as working components, so visitors can explore the original material within the exhibition.'],
    },
  },
  {
    id: 'rooms', label: 'Rooms', title: 'A route shaped by the reading', image: 'rooms', caption: 'The visit map',
    copy: 'Each View creates a different sequence of rooms. Their size and arrangement follow the selected works. A floor plan shows the rooms and individual exhibits, letting visitors choose where to go next.',
    alt: 'The visit map shows the generated rooms, their connections and individual works',
    mechanism: {
      title: 'How the rooms are composed',
      paragraphs: ['The layout algorithm groups works by chapter and sizes each room around their display forms and viewing distances. It arranges entrances, wall introductions and exhibits, then connects the rooms with doorways and a walkable route.'],
    },
  },
  {
    id: 'lighting', label: 'Lighting', title: 'Lighting the visit', image: 'lighting', video: 'lighting', caption: 'Room lighting',
    copy: 'Rooms gradually brighten as visitors approach and dim as they leave. The light draws attention to the next room along the route.',
    mechanism: {
      title: 'How light follows the visitor',
      paragraphs: ['The visitor’s position and distance from a doorway determine which rooms are lit. Each room’s lights fade together, making the next space visible as the visitor approaches its threshold.'],
    },
  },
  {
    id: 'audio', label: 'Audio guide', title: 'An audio guide in my voice', image: 'audio', video: 'audio', caption: 'Audio guide', sound: true,
    copy: 'An AI voice trained on my recordings narrates the exhibition as visitors walk. Listening gives them space to look around and spend time with the works as they follow the story.',
    mechanism: {
      title: 'How narration follows the visit',
      paragraphs: ['Narration connects each passage to a viewing position. A passage can finish as the visitor moves, and the next begins once they arrive. The reading panel follows the active passage, with word highlighting synchronised to playback.', 'Listening progress is remembered for each passage, so visitors can pause, explore a work and pick up where they left off.'],
    },
  },
  {
    id: 'language', label: 'Language', title: 'Reading in another language', image: 'translation', video: 'translation', caption: 'Chinese → English',
    copy: 'Translation lets visitors follow the exhibition in their own language and engage more closely with the ideas behind the works.',
  },
];

export default {
  components: { GalleryStudyFilm, ExpandableProjectMedia, ExhibitionFeatureIcon },
  data: () => ({ selected: 'arrival', features }),
  computed: { maskId() { return `rooms-study-mask-${this.$.uid}`; } },
  methods: {
    tabId(id) { return `experience-${this.$.uid}-${id}-tab`; },
    panelId(id) { return `experience-${this.$.uid}-${id}`; },
    image(name) { return `/assets/img/projects/gallery-experience/${name}.webp${name === 'translation' ? '' : '?v=20260920'}`; },
    film(name, extension = 'mp4') { return `/assets/video/gallery-experience/${name}.${extension}${name === 'translation' ? '' : '?v=20260920'}`; },
    async moveTab(event) {
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
      event.preventDefault();
      const index = this.features.findIndex(feature => feature.id === this.selected);
      const next = event.key === 'Home' ? 0 : event.key === 'End' ? this.features.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : -1) + this.features.length) % this.features.length;
      this.selected = this.features[next].id;
      await this.$nextTick();
      const tab = document.getElementById(this.tabId(this.selected));
      tab?.focus({ preventScroll: true });
    },
  },
};
</script>
