.experience-tabs button { position: relative; display: flex; flex-direction: column; align-items: center; gap: .55rem; appearance: none; border: 0; padding: .8rem .35rem 1rem; background: none; color: var(--site-text-secondary); font: 14px/1.4 'Quattrocento Sans', sans-serif; white-space: nowrap; cursor: var(--site-interactive-cursor, pointer); transition: color 160ms; }
.experience-tabs button::after { content: ''; position: absolute; inset: auto 14% -1px; height: 1px; background: currentColor; opacity: 0; transition: opacity 160ms; }
