button:focus-visible, summary:focus-visible, .experience-panel:focus-visible { outline: 1px solid currentColor; outline-offset: 5px; }
@media (hover: hover) and (pointer: fine) { .experience-tabs button:hover { color: var(--site-text-primary); } .experience-tabs button:hover :deep(.exhibition-feature-icon) { opacity: 1; transform: translateY(-2px); } }
@media (max-width: 760px) {
  .experience-row { grid-template-columns: 1fr; gap: 1.2rem; }
  .experience-tabs { grid-template-columns: repeat(8, minmax(0, 1fr)); row-gap: .3rem; padding-bottom: .8rem; margin-bottom: 1.4rem; }
  .experience-tabs button { grid-column: span 2; min-width: 0; gap: .35rem; padding: .6rem 0 .75rem; font-size: 12px; }
  .experience-tabs button:nth-child(5) { grid-column: 2 / span 2; }
  .experience-tabs button:nth-child(6) { grid-column: 4 / span 2; }
  .experience-tabs button:nth-child(7) { grid-column: 6 / span 2; }
  .experience-tabs button::after { inset-inline: 28%; bottom: 0; }
  .experience-tabs :deep(.exhibition-feature-icon) { width: 30px; height: 30px; }
  .experience-tabs button:focus-visible { outline-offset: -2px; }
  .experience-copy { grid-row: 2; padding: 0; }
}
@media (prefers-reduced-motion: reduce) { .experience-tabs button, .experience-tabs button::after, .experience-tabs :deep(.exhibition-feature-icon) { transition: none; transform: none !important; } }
